WITH customer_totals AS (SELECT customer_id, MAX(monthly_fee) AS max_monthly_fee, ROUND(AVG(monthly_fee), 2) AS avg_monthly_fee FROM subscriptions WHERE customer_id IN (1, 2, 40) GROUP BY customer_id) SELECT c.segment, c.country, ct.max_monthly_fee, ct.avg_monthly_fee FROM customers c JOIN customer_totals ct ON c.id = ct.customer_id WHERE ct.max_monthly_fee > 230 ORDER BY max_monthly_fee DESC
